(function(){
 const canvas=document.querySelector('#stage'),ctx=canvas.getContext('2d');let state=null,action=null,started=0,duration=0;
 function figure(x,y,scale,color,enemy,dead,move=0){ctx.save();ctx.translate(x+move,y);ctx.scale(scale,scale);if(dead)ctx.globalAlpha=.25;ctx.fillStyle='#07111b88';ctx.beginPath();ctx.ellipse(0,0,32,9,0,0,7);ctx.fill();ctx.strokeStyle=enemy?'#928b94':'#c0c7d2';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(-8,-58);ctx.lineTo(-17,-5);ctx.moveTo(8,-58);ctx.lineTo(20,-5);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-16,-110);ctx.lineTo(15,-110);ctx.lineTo(25,-53);ctx.lineTo(-24,-53);ctx.closePath();ctx.fill();ctx.fillStyle=enemy?'#a39ba6':'#e8d5c6';ctx.beginPath();ctx.ellipse(0,-130,12,18,0,0,7);ctx.fill();ctx.fillStyle=enemy?'#303343':'#263c50';ctx.beginPath();ctx.moveTo(-14,-142);ctx.lineTo(1,-152);ctx.lineTo(14,-136);ctx.lineTo(6,-132);ctx.lineTo(-12,-139);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-12,-100);ctx.lineTo(-33,-65);ctx.moveTo(12,-100);ctx.lineTo(32,-82);ctx.stroke();ctx.strokeStyle='#d1e8eb';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(32,-82);ctx.lineTo(enemy?42:57,enemy?-118:-130);ctx.stroke();ctx.restore()}
 function draw(){const t=performance.now();const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,dpr=devicePixelRatio||1;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#0c1725');g.addColorStop(.55,'#243748');g.addColorStop(1,'#304251');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);const horizon=h*.38;ctx.strokeStyle='#7894ac1c';ctx.lineWidth=1;for(let i=-8;i<12;i++){ctx.beginPath();ctx.moveTo(w*.52,horizon);ctx.lineTo(i*w*.15,h);ctx.stroke()}for(let j=0;j<7;j++){let y=horizon+(h-horizon)*Math.pow(j/6,1.7);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#8db9cf25';ctx.lineWidth=8;for(let i=0;i<6;i++){ctx.beginPath();ctx.moveTo(i*w*.19-30,0);ctx.lineTo(i*w*.19+70,horizon);ctx.stroke()}ctx.fillStyle='#98649b15';ctx.beginPath();ctx.moveTo(w*.65,0);ctx.lineTo(w,0);ctx.lineTo(w,horizon);ctx.lineTo(w*.58,horizon);ctx.fill();if(state){const mobile=w<760,base=document.getElementById('allies').getBoundingClientRect().top-r.top-18,scale=mobile?.64:Math.min(1.1,w/1100),allyRight=Math.min(w*.54,document.getElementById('enemies').getBoundingClientRect().left-r.left-60);state.allies.forEach((a,i)=>{let move=action===a.id?Math.sin(Math.min(1,(t-started)/duration)*Math.PI)*18:0;figure(mobile?w*(.15+i*.23):w*.1+i*(allyRight-w*.1)/3,base,scale,a.color,false,a.hp<=0,move)});state.enemies.forEach((a,i)=>figure(w*(mobile?.57+i*.25:.69+i*.17),mobile?h*.38:h*.51,mobile?.65:.86,i?'#96769a':'#b9a67f',true,a.hp<=0,0))}requestAnimationFrame(draw)}requestAnimationFrame(draw);
 window.PartyV3Stage={set:s=>{state=s},animate:(actor,ms)=>{action=actor;started=performance.now();duration=ms||1}};
})();
